const upsertAgentGrant = `-- name: UpsertAgentGrant :one
with g as (
    insert into agent_project_permissions (agent_id, project_id, scopes)
    values ($1, $2, $3::text[])
    on conflict (agent_id, project_id) do update set scopes = excluded.scopes
    returning agent_id, project_id, scopes, created_at
)
select g.agent_id, g.project_id, g.scopes, g.created_at, p.key as project_key, p.name as project_name
from g join projects p on p.id = g.project_id
`

type UpsertAgentGrantParams struct {
	AgentID   pgtype.UUID `json:"agent_id"`
	ProjectID pgtype.UUID `json:"project_id"`
	Scopes    []string    `json:"scopes"`
}

type UpsertAgentGrantRow struct {
	AgentID     pgtype.UUID        `json:"agent_id"`
	ProjectID   pgtype.UUID        `json:"project_id"`
	Scopes      []string           `json:"scopes"`
	CreatedAt   pgtype.Timestamptz `json:"created_at"`
	ProjectKey  string             `json:"project_key"`
	ProjectName string             `json:"project_name"`
}

func (q *Queries) UpsertAgentGrant(ctx context.Context, arg UpsertAgentGrantParams) (UpsertAgentGrantRow, error) {
	row := q.db.QueryRow(ctx, upsertAgentGrant, arg.AgentID, arg.ProjectID, arg.Scopes)
	var i UpsertAgentGrantRow
	err := row.Scan(
		&i.AgentID,
		&i.ProjectID,
		&i.Scopes,
		&i.CreatedAt,
		&i.ProjectKey,
		&i.ProjectName,
	)
	return i, err
}
